# Tense id -> (verbecc mood, verbecc tense).
TENSES = {
    'it': {
        'presente': ('indicativo', 'presente'),
        'passato': ('indicativo', 'passato-prossimo'),
        'futuro': ('indicativo', 'futuro'),
        'imperfetto': ('indicativo', 'imperfetto'),
        'condizionale': ('condizionale', 'presente'),
    },
    'es': {
        'presente': ('indicativo', 'presente'),
        'perfecto': ('indicativo', 'pretérito-perfecto-compuesto'),
        'indefinido': ('indicativo', 'pretérito-perfecto-simple'),
        'imperfecto': ('indicativo', 'pretérito-imperfecto'),
        'futuro': ('indicativo', 'futuro'),
        'condicional': ('condicional', 'presente'),
    },
}
# The six persons of the trainer and the verbecc pronouns each stands for.
PERSONS = {
    'it': [['io'], ['tu'], ['lui', 'lei'], ['noi'], ['voi'], ['loro']],
    'es': [['yo'], ['tú'], ['él', 'ella', 'usted'], ['nosotros'], ['vosotros'], ['ellos', 'ellas', 'ustedes']],
}
# Imperative persons: slot -> verbecc pronoun (the other slots stay empty).
IMPERATIVE = {
    'it': {1: 'tu', 3: 'noi', 4: 'voi'},
    'es': {1: 'tú', 2: 'usted', 3: 'nosotros', 4: 'vosotros'},
}
# Archaic or literary variants verbecc lists next to the usual form; a learner never needs them.
ARCHAIC = {'fo', 'vò', 'vo', 'debbo', 'debbono', 'rimaso', 'rimasa', 'rimasi', 'rimase'}


def strip(form: str, pronouns: list[str]) -> str:
    for p in pronouns:
        if form.startswith(p + ' '):
            return form[len(p) + 1:]
    return form


def cell(rows: list[dict], wanted: list[str], all_pronouns: list[str]) -> list[str]:
    """All forms for a person: variants ("devo/debbo") and both genders, masculine first."""
    forms: list[tuple[int, str]] = []
    for r in rows:
        if r['pr'] not in wanted:
            continue
        feminine = 1 if r.get('g') == 'f' else 0
        for c in r['c']:
            for variant in strip(c, all_pronouns).split('/'):
                variant = variant.strip()
                if variant and variant != '-' and variant not in ARCHAIC:
                    forms.append((feminine, variant))
    out: list[str] = []
    for _, f in sorted(forms, key=lambda x: x[0]):
        if f not in out:
            out.append(f)
    return out


def imperative(lang: str, conj, inf: str, group: str, moods: dict) -> list[list[str]]:
    slots: list[list[str]] = [[] for _ in range(6)]
    if group == 'modal' or (lang == 'es' and group == 'reflexive'):
        # Modals have no imperative in everyday use; Spanish reflexive imperatives
        # (levántate, levantaos) are taught in the lesson, not drilled here.
        return slots
    pronouns = [p for ps in PERSONS[lang] for p in ps]
    if group == 'reflexive':
        # Italian: the pronoun is joined to the end: alza + ti = alzati, alziamoci, alzatevi.
        base = json.loads(str(conj.conjugate(inf[:-2] + 'e')))['moods']['imperativo']['affermativo']
        for slot, suffix in ((1, 'ti'), (3, 'ci'), (4, 'vi')):
            slots[slot] = [f + suffix for f in cell(base, [IMPERATIVE[lang][slot]], pronouns)]
        return slots
    rows = moods['imperativo']['affermativo' if lang == 'it' else 'afirmativo']
    for slot, pr in IMPERATIVE[lang].items():
        forms = cell(rows, [pr], pronouns)
        # "fa" next to "fa'": only the apostrophe form is right in the Italian imperative.
        slots[slot] = [f for f in forms if f + "'" not in forms]
    return slots


def main() -> None:
    lang = sys.argv[1] if len(sys.argv) > 1 else 'it'
    conj = CompleteConjugator(lang)
    pronouns = [p for ps in PERSONS[lang] for p in ps]
    out = []
    for inf, ru, az, group in VERBS[lang]:
        moods = json.loads(str(conj.conjugate(inf)))['moods']
        tenses = {}
        for tid, (mood, tense) in TENSES[lang].items():
            rows = moods[mood][tense]
            tenses[tid] = [cell(rows, ps, pronouns) for ps in PERSONS[lang]]
        tenses['imperativo'] = imperative(lang, conj, inf, group, moods)
        out.append({'inf': inf, 'ru': ru, 'az': az, 'group': group, 'forms': tenses})
    print('// Generated by scripts/build_verbs.py (forms from verbecc). Do not edit by hand.')
    print("import type { Verb } from '../types';\n")
    print('export const VERBS: Verb[] = [')
    for v in out:
        forms = ',\n'.join(f'      {t}: {json.dumps(cells, ensure_ascii=False)}' for t, cells in v['forms'].items())
        head = json.dumps({k: v[k] for k in ('inf', 'ru', 'az', 'group')}, ensure_ascii=False)[1:-1]
        print(f'  {{ {head},\n    forms: {{\n{forms},\n    }},\n  }},')
    print('];')


if __name__ == '__main__':
    main()
